function largestNumber(numbers) {
    // הולך לרשימה מספרים
    let max = numbers[0];

    // הולך ל深处 של הרשימה
    for (let i = 1; i < numbers.length; i++) {
        if (numbers[i] > max) {
            // אם מספר חדש גדול יותר compared to previous number
            max = numbers[i];
        }
    }

    return max;
}
```

